from pathlib import Path
from datetime import datetime, timezone
import hashlib, json

R = Path('/workspace/research')
K = R / 'root-checks'
S = R / 'primary-data-LOCALONLY/P16.7-Ducros2012-local-tropical-dimension-20261009'
O = K / 'P16.7-Ducros2012-local-dimension-ROOT-primary-reading-and-version-scope-20261009.json'
assert S.exists() and not O.exists()
sha = lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest()
assert sha(K / 'public-P16-round-46-final-reader/P16.4-paper.tex') == '09a83320fbb8fd7f468329307136ccaa146ea4ad07e9a23437ec3dd688ed942a'
T = S / 'Ducros2012-author-tropicbis.txt'
assert sha(T) == 'fcc6089cdfc1471362cad4ca699c69b15b6937cb800b5e9e78a76a54aac2511a'
lines = T.read_text().splitlines(keepends=True)
units = []
for lo, hi, label in [(1206, 1476, 'Entire Lemma1.1 and Theorem1.2 with immediate proofs'), (1476, 1578, 'Entire Theorem1.3 including reductions1.3.1-4'), (2127, 2260, 'Entire local Theorem3.4 statement and immediate proof plus context')]:
    p = S / ('ROOT-full-local-dimension-dependency-LF%d-%d-LOCALONLY.txt' % (lo, hi))
    assert not p.exists()
    p.write_text(''.join(lines[lo-1:hi]))
    units.append(dict(path=str(p), bytes=p.stat().st_size, sha256=sha(p), source=str(T), literal_LF_inclusive=[lo, hi], content=label, ROOT_full_physical_read_untruncated=True, LOCALONLY=True))
pixels = []
for stem, pages in [('ROOT-local-dimension-proof', [39, 40, 41]), ('ROOT-graded-valuative-image-proof', [27, 28, 29])]:
    for n in pages:
        p = S / ('%s-%d.png' % (stem, n))
        assert p.is_file()
        pixels.append(dict(path=str(p), bytes=p.stat().st_size, sha256=sha(p), actual_PDF_page_and_printed_page=n, ROOT_entire_page_original_detail_physically_viewed=True, LOCALONLY=True))
errata = []
for stem, expected in [('Ducros2013-author-erratum', '7748cd9c1558a87d3d7691350e3a980a34604ce03fe348e84700c351f5af39d7'), ('Ducros2013-official-DOI-cml7-erratum', '0dfe587f2dc5d5070e2a4c28f16ca29990fda6247ceaf4bfef9f2206d7251fcd')]:
    p = S / (stem + '.txt')
    assert sha(p) == expected
    errata.append(dict(path=str(p), bytes=p.stat().st_size, sha256=sha(p), ROOT_entire_text_physically_read_untruncated=True, complete_replacement_proof_read=True, LOCALONLY=True))
out = dict(
    recorded_utc=datetime.now(timezone.utc).isoformat(),
    status='New ROOT primary-source reading and qualified dependency record; NOT a draft acceptance or original closure',
    qualified_application='Only the local tropical image dimension upper bound at a point by the graded transcendence degree of the field generated by the moment-coordinate residues; gamma-strict hypothesis must be checked. Applied to whole387 common four-coordinate moment chart. Bounded product/support premises still require their separate whole-proof review.',
    original_reference=dict(author='Antoine Ducros', title='Espaces de Berkovich, polytopes, squelettes et theorie des modeles', journal='Confluentes Mathematici 4(2012), no4, article1250007,57pp', doi='10.1142/S1793744212500077', arxiv='1203.6498', CLDv2_reference=50),
    retrieved_version='tropicbis.pdf is the later retrieved author version containing numbered local Theorem3.4. tropic.pdf is the earlier retrieved author version without this numbered local theorem. No revision date or identity with the official 2012 PDF is inferred.',
    full_read_units=units,
    primary_PDF_pixels=pixels,
    full_erratum_texts=errata,
    printed_typographical_errors=[
        dict(location='tropicbis.pdf printed page27, Theorem1.3 first paragraph', actually_printed='The homogeneous nonzero fi are said to belong to K', mathematical_interpretation='They belong to L. The proof1.3.1-4 explicitly works in L and its generated subfield, and Theorem3.4 explicitly applies them in the graded residue extension. If they belonged to K all d would be zero.', evidence='Actual full PDF page27 viewed; printed K is real, not an OCR artifact.', repair_scope='Documented interpretation from the entire immediate proof, not a claim that the author PDF printed L.'),
        dict(location='tropicbis.pdf printed page41, first formula in Theorem3.4 proof', actually_printed='psi_i,j <= phi_i,j(xi)', mathematical_interpretation='psi_i,j <= psi_i,j(xi)', evidence='Full PDF pages39-41 viewed. Page40 defines Q with psi on both sides and derives exactly that inequality immediately before the page41 typo.', repair_scope='Upper dimension bound follows already from the containing translated rational cone P. No erroneous formula is used to infer the upper bound.')
    ],
    erratum_dependency_scope='The 2013 erratum repairs the page36 proof of finite definable norm functions universally separating Gauss valuation-extension fibers. Its extra ingredients are [14]Lemma3.4.12 and [15]Lemma6.2.2. The local dimension upper-bound chain is Theorem3.4 -> Theorem1.3(1) -> Theorem1.2(A,B) -> Lemma1.1 / ordinary valuation and ACVF foundations; it does not use the repaired section2 separation result.',
    version_metadata_correction='Official erratum PDF has pages47-48, author erratum PDF43-44. BOTH actual PDF texts print received6September2013/revised9September2013/accepted9September2013. The journal web metadata instead lists received8June2013/revised8September2013/accepted8September2013. The earlier retrieval record referred to web metadata and incorrectly suggested the actual PDFs had different received dates. This record supersedes that suggestion and preserves the distinction between web metadata and actual PDF text.',
    deeper_background_not_newly_full_proof_read=['Temkin germ reduction0.22 and its original proof tree', 'ACVF quantifier elimination, model completeness and compactness foundational proofs', 'General valuation-extension existence and implicit-function foundational proofs', 'Erratum references[14]Lemma3.4.12 and[15]Lemma6.2.2 foundational proofs'],
    no_recursive_source_tree_completion_claim=True,
    all_full_primary_bodies_literal_units_pixels_and_book_context_LOCALONLY=True,
    supplied_or_native_programs_executed_or_imported=False,
    no_active_native_math_read_or_hot_feedback=True,
    new_correctness_grant=False,
    original_closed=False,
    accepted_paper=False,
    counts=dict(solved=16, open=26, accepted_scoped_papers=97),
    protected_editor_OPEN_UNCHANGED=True
)
O.write_text(json.dumps(out, ensure_ascii=False, indent=2) + '\n')
print(json.dumps(dict(record=str(O), bytes=O.stat().st_size, sha256=sha(O), full_literal_units=len(units), full_PDF_pages_viewed=len(pixels), full_erratum_texts=len(errata), original_closed=False, accepted_paper=False), indent=2))
